def lin(c):
    c/=255
    return c/12.92 if c<=.03928 else ((c+.055)/1.055)**2.4
def L(x): return .2126*lin(x>>16&255)+.7152*lin(x>>8&255)+.0722*lin(x&255)
def cr(a,b):
    a,b=L(a),L(b)
    if a<b:a,b=b,a
